'use strict';

// MODULES //

var max = require( '@stdlib/math/base/special/max' );
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var validate = require( './validate.js' );


// MAIN //

/**
* Creates both public APIs with one validation and dispatch contract.
* @private
* @param {Function} backend - normalized routine
* @param {Function} [eligible] - optional native eligibility
* @param {Function} [fallback] - validated JavaScript routine
* @returns {Function} interface
*/
function factory(backend, eligible, fallback) {
	setReadOnly(dgbtf2, 'ndarray', ndarray);
	return dgbtf2;
	/**
* Factors compact band storage using a contiguous layout.
* @private
* @param {string|integer} order - layout
* @param {integer} M - rows
* @param {integer} N - columns
* @param {integer} KL - lower bandwidth
* @param {integer} KU - upper bandwidth
* @param {Float64Array} AB - band storage
* @param {integer} LDAB - leading dimension
* @param {Int32Array} PIV - one-based step swaps
* @throws {TypeError} invalid selector
* @throws {RangeError} invalid scalar or leading dimension
* @returns {integer} INFO
*/
	function dgbtf2(order, M, N, KL, KU, AB, LDAB, PIV) {
		var column;
		var shape;
		if (((((order !== 'row-major') && (order !== 'column-major')) && (order !== 101)) && (order !== 102))) {
			throw new TypeError('invalid argument. Invalid layout.');
		}
		shape = validate.scalars(M, N, KL, KU);
		validate.integer(LDAB);
		column = ((order === 'column-major') || (order === 102));
		if ((LDAB < (( column ) ? shape.h : max(1, N)))) {
			throw new RangeError('invalid argument. Invalid leading dimension.');
		}
		if (shape.empty) {
			return 0;
		}
		return ndarray(M, N, KL, KU, AB, ( column ) ? 1 : LDAB, ( column ) ? LDAB : 1, 0, PIV, 1, 0);
	}
	/**
* Factors independent indexed views.
* @private
* @param {integer} M - rows
* @param {integer} N - columns
* @param {integer} KL - lower bandwidth
* @param {integer} KU - upper bandwidth
* @param {Float64Array} AB - band storage
* @param {integer} r - row stride
* @param {integer} c - column stride
* @param {integer} o - band offset
* @param {Int32Array} PIV - one-based step swaps
* @param {integer} sp - pivot stride
* @param {integer} op - pivot offset
* @throws {TypeError} invalid intrinsic storage
* @throws {RangeError} invalid scalar, view or backend status
* @returns {integer} INFO
*/
	function ndarray(M, N, KL, KU, AB, r, c, o, PIV, sp, op) { // eslint-disable-line max-params
		var shape;
		var info;
		var use;
		shape = validate.scalars(M, N, KL, KU);
		if (shape.empty) {
			return 0;
		}
		validate(shape, N, AB, r, c, o, PIV, sp, op);

		// Normalize only metadata which cannot select another logical cell.
		r = (shape.h === 1) ? 1 : r;
		c = (N === 1) ? 1 : c;
		sp = (shape.k === 1) ? 1 : sp;
		use = (eligible && !eligible(M, N, KL, KU, AB, r, c, o, PIV, sp, op)) ? fallback : backend;
		info = use(M, N, KL, KU, AB, r, c, o, PIV, sp, op);
		if ((info < 0)) {
			throw new RangeError('invalid argument. The private routine rejected the normalized view.');
		}
		return info;
	}
}


// EXPORTS //

module.exports = factory;
